export function recordedRoster(units,observedAt){
 const source=(id,unitNumber,placement,extra={})=>({id,kind:'source_equipment',unitId:null,unit:null,unitNumber,placement,lifecycle:'active',active:true,source:'owner_supplied_mhelp_export',observedAt,productIds:[id.split(':')[1]],sourceRecordIds:[],representedUnitIds:[],customer:'Synthetic source customer',sourceAddress:{street:'555 Synthetic customer address'},reviewReason:'No verified COS unit link is available.',family:'RANGER',category:'Synthetic equipment',...extra});
 const items=units.map((unit,i)=>({id:'cos_unit:'+unit.id,kind:'unit',unitId:unit.id,unit,unitNumber:unit.unitNumber,placement:unit.currentLocationType,lifecycle:'active',active:true,source:i===0?'owner_supplied_mhelp_export':'owner',observedAt,productIds:i===0?['5001']:[],sourceRecordIds:[],representedUnitIds:[unit.id],customer:unit.customer||null,sourceAddress:null,reviewReason:null}));
 items.push(source('mhelp_product:7001','Ranger 901','field'),source('tracker_row:synthetic-902','Recon II 902','field',{source:'current_tracker',productIds:[],sourceRecordIds:['synthetic-902'],family:'RECON2'}),source('mhelp_product:7002','Ranger 902','shop'),source('mhelp_product:7003','Ranger 903','field',{lifecycle:'do_not_use',active:false}),source('tracker_row:synthetic-review','Ranger 999.1','unknown',{kind:'identity_review',source:'current_tracker',productIds:[],sourceRecordIds:['synthetic-review'],reviewReason:'Conflicting source identities need review.'}));
 const active=items.filter(r=>r.active);
 return {contract:'COS_COMBINED_FLEET_ROSTER_V1',items,summary:{totalRecords:items.length,activeRecords:active.length,field:active.filter(r=>r.placement==='field').length,shop:active.filter(r=>r.placement==='shop').length,review:active.filter(r=>r.placement==='unknown').length,excludedLifecycle:items.length-active.length,sourceOnlyRecords:items.filter(r=>r.kind!=='unit').length,linkedUnitRecords:items.filter(r=>r.kind==='unit').length},countBasis:'equipment_records_with_reviewed_cross_source_links',physicalDeduplication:'incomplete'};
}
